bParentPageExists = false;
ClipboardPage pgReport = tools.getPrimaryPage();
ClipboardPage pgParent = pgReport.getParentPage();
if(pgParent != null) {
         if(pgParent.getParentPage() != null) {
	     bParentPageExists = true;
              contentPageToCopy = pgParent.getReference();
              contentpage = pgParent.getReference();
              reportpage = pgReport.getReference();
         } else {
	     bParentPageExists = true;
              contentPageToCopy = pgParent.getReference();
              contentpage = pgParent.getReference();
              reportpage = pgReport.getReference();
         }
} else {
   contentPageToCopy = pgReport.getString(".pyContent.pyContentPageName");

}

String strReportToDisplay = contentpage;

ClipboardPage pg_usingPage = null;
if(strReportToDisplay.indexOf(".") > 0) {
   ClipboardProperty cp_usingPage= tools.getIfPresent(strReportToDisplay);
   if(cp_usingPage!=null)
   {
   	pg_usingPage= cp_usingPage.getPageValue();								
   }
} else {
   pg_usingPage = tools.findPage(strReportToDisplay);
}
if(pg_usingPage.getIfPresent(".pyPreparedValues") != null) {
	pg_usingPage.getProperty(".pyPreparedValues").removeFromClipboard();
}

boolean iscustomRow = myStepPage.getBoolean(".pyUI.pyBody.pyCustomRowEnabled");
boolean isSummary = myStepPage.getBoolean(".pyContent.pxIsSummary");
boolean reportDesignMode = myStepPage.getBoolean(".pzReportDesignMode");
boolean isSmartInfoEnabled = myStepPage.getBoolean(".pyUI.pySmartInfo.pySingleClickSInfo.pyEnabled");
String eMode = tools.getParamValue("exportmode");

if(!iscustomRow && !isSummary  &&  !reportDesignMode && eMode.equals("")  && !isSmartInfoEnabled)
{
            myStepPage.getProperty(".pyListFlow").setValue(true);
}
else
{
          myStepPage.getProperty(".pyListFlow").setValue(false);
}

ClipboardPage cpTarget = tools.getStepPage();
ClipboardPage cpPrimary = tools.getPrimaryPage();
String modelClass = cpPrimary.getString(".pyClassName");


ParameterPage pyTempListOfAvailableProps= tools.getParameterPage();
try{
StringMap params1 = new HashStringMap(3);
                params1.putString("pxObjClass", "Rule-Obj-Model");
                params1.putString("pyClassName", modelClass);
                params1.putString("pyModelName", "pyReportEditorProperties");
ClipboardPage cpModel = tools.getDatabase().open(params1,false);
if(cpModel ==null || (cpModel.getProperty(".pyProperties").size() == 1 && "COMMENT".equals(cpModel.getPage(".pyProperties(1)").getString(".pyActionName")))){
cpTarget.putString(".pyUseDTForProperties","false");
}
else{
cpTarget.putString(".pyUseDTForProperties","true");
}
}
catch(Exception ex) {
cpTarget.putString(".pyUseDTForProperties","false");
}
